arguments:
"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$plan = '"'plans\\hello-cli'
"'$files = Get-ChildItem -LiteralPath $plan -File | Sort-Object Name
$taskLines = Select-String -Path (Join-Path $plan '"'99-execution-plan.md') -Pattern '"'^- '"\\[ \\] [0-9]+\\.[0-9]+\\.[0-9]+ ' | ForEach-Object { "'$_.Line }
$stRows = Select-String -Path (Join-Path $plan '"'07-testing-strategy.md') -Pattern '"'^'"\\| ST-[0-9]+ \\|' | ForEach-Object { "'$_.Line }
$rawGit = Select-String -Path (Join-Path $plan '"'*.md') -Pattern '\\bgit (add|commit|push)\\b'
"'$placeholders = Select-String -Path (Join-Path $plan '"'*.md') -Pattern '\\[(Feature Name|Date|YYYY-MM-DD|Project.s verify command|Requirement 1)\\]'
"'$graph = Get-Content -Raw -LiteralPath '"'traceability.json' | ConvertFrom-Json
"'$nodes = @{}
foreach ($node in $graph.nodes) { $nodes[$node.id] = $node }
$requirements = @('"'RD-01','RD-02','RD-03') | ForEach-Object {
  "'$node = $nodes[$_]
  [pscustomobject]@{
    Id = $_
    Specified = @($node.edges | Where-Object relation -eq '"'specified-by').Count
    Accepted = @("'$node.edges | Where-Object relation -eq '"'accepted-by').Count
  }
}
"'$criteria = @('"'CRIT-01','CRIT-02','CRIT-03') | ForEach-Object {
  "'$node = $nodes[$_]
  [pscustomobject]@{
    Id = $_
    Tested = @($node.edges | Where-Object relation -eq '"'tested-by').Count
    Implemented = @("'$node.edges | Where-Object relation -eq '"'implemented-by').Count
  }
}
Write-Output ('Documents: ' + (("'$files.Name) -join '"', '))
Write-Output ('Task lines: ' + "'$taskLines.Count)
Write-Output ('"'Unique task lines: ' + (@("'$taskLines | Sort-Object -Unique).Count))
Write-Output ('"'ST rows: ' + "'$stRows.Count)
Write-Output ('"'Raw git commands: ' + @("'$rawGit).Count)
Write-Output ('"'Template placeholders: ' + @("'$placeholders).Count)
Write-Output ('"'Implementation files present: ' + @((Test-Path -LiteralPath 'hello.py'), (Test-Path -LiteralPath 'tests') | Where-Object { "'$_ }).Count)
$requirements | Format-Table -AutoSize
$criteria | Format-Table -AutoSize
Write-Output ('"'Plan status: ' + "'$nodes['"'PLAN-01'].status)
Write-Output ('Planning group status: ' + "'$nodes['"'PG-01'].status)
Write-Output ('Specification statuses: ' + (("'$nodes['"'SPEC-01'].status, "'$nodes['"'SPEC-02'].status) -join ', '))"

