"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$root = (Resolve-Path '"'.').Path
"'$broken = @()
Get-ChildItem -LiteralPath '"'plans\\hello-cli' -Filter '*.md' | ForEach-Object {
  "'$source = $_
  $text = Get-Content -Raw -LiteralPath $source.FullName
  [regex]::Matches($text, '"'\\[["'^'"\\]]+\\]\\((["'^)#]+)(?:#[''^)]+)?'"\\)') | ForEach-Object {
    "'$targetText = $_.Groups[1].Value
    if ($targetText -notmatch '"'"'^[a-z]+:'"' -and "'$targetText -notmatch '"'"'^#'"') {
      "'$targetPath = [System.IO.Path]::GetFullPath((Join-Path $source.DirectoryName $targetText))
      if (-not (Test-Path -LiteralPath $targetPath)) {
        $broken += [pscustomobject]@{ Source = $source.Name; Target = $targetText }
      }
    }
  }
}
$taskIds = Select-String -Path '"'plans\\hello-cli\\99-execution-plan.md' -Pattern '"'^- '"\\[ \\] ([0-9]+\\.[0-9]+\\.[0-9]+) ' | ForEach-Object { "'$_.Matches[0].Groups[1].Value }
$stIds = Select-String -Path '"'plans\\hello-cli\\07-testing-strategy.md' -Pattern '"'^'"\\| (ST-[0-9]+) \\|' | ForEach-Object { "'$_.Matches[0].Groups[1].Value }
$arIds = Select-String -Path '"'plans\\hello-cli\\00-ambiguity-register.md' -Pattern '"'^'"\\| AR-([0-9]+) \\|' | ForEach-Object { [int]"'$_.Matches[0].Groups[1].Value }
Write-Output ('"'Broken local links: ' + "'$broken.Count)
Write-Output ('"'Task sequence: ' + ("'$taskIds -join '"', '))
Write-Output ('ST sequence: ' + ("'$stIds -join '"', '))
Write-Output ('Plan AR sequence: ' + (("'$arIds | Sort-Object) -join '"', '))
git diff --stat"

